INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT156-S4-Q14$batch02$, 156, 4, 14, $batch02$Flaw$batch02$, $batch02$Science writer: Scientists often accept a scientific argument largely for social reasons, such as the argument’s acceptance by other scientists or the prestige of the scientist making the argument. But this is not at all to the sciences’ detriment, for similar social factors strongly influence every human endeavor.$batch02$, $batch02$The science writer’s argument is most vulnerable to criticism on the grounds that it$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$takes for granted that the only legitimate reasons for accepting an argument are social reasons$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$takes for granted that whether a behavior obstructs the achievement of a particular endeavor’s goals depends on the prevalence of comparable behaviors in other endeavors$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$fails to consider the possibility that scientists who accept an argument largely for social reasons also generally consider relevant scientific evidence before accepting the argument$batch02$, $batch02$Strengthens, if anything$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$fails to consider the possibility that many scientists are unaware that they usually accept scientific arguments largely for social reasons$batch02$, $batch02$No Impact$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$takes for granted that a behavior that is not detrimental to the sciences will not be detrimental to any other human endeavor$batch02$, $batch02$Backwards$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Accepting arguments for social reasons does not harm the sciences.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Social factors strongly influence every human endeavor.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$"Everyone does it" is not "it does no harm here." Cheating happens in many games; it still ruins chess. Science has a particular goal: finding out what is true. Accepting an argument because of who made it could get in the way of that goal no matter how common the habit is elsewhere. The writer moves from *widespread* to *harmless*.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the assumption that how common a behavior is elsewhere decides whether it hurts science.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The writer never says social reasons are the only legitimate ones. The writer only says relying on them does no harm.$batch02$), ($batch02$B$batch02$, $batch02$Map the abstract wording. "A behavior" is accepting arguments for social reasons. "A particular endeavor's goals" are science's goals. "Comparable behaviors in other endeavors" is social influence on every human endeavor. The writer treats the fact that social influence is everywhere as settling whether it obstructs science. It does not.$batch02$), ($batch02$C$batch02$, $batch02$If scientists also weigh the evidence, social reasons are less likely to harm science. That helps the writer rather than exposing a flaw.$batch02$), ($batch02$D$batch02$, $batch02$Whether scientists notice their social motives does not affect whether those motives harm science.$batch02$), ($batch02$E$batch02$, $batch02$The writer reasons from other endeavors to science, not from science to other endeavors. Nothing is concluded about whether the behavior harms anything else.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT156-S4-Q14$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
